// Simple canvas game based on IDEA.md – Space Drift
// Assumes a <canvas id="game"></canvas> exists in the HTML.
(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const WIDTH = canvas.width = canvas.clientWidth || 800;
  const HEIGHT = canvas.height = canvas.clientHeight || 600;

  // ----- Game state -----
  const ship = { x: WIDTH / 2, y: HEIGHT - 60, size: 20, speed: 4 };
  let asteroids = [];
  let powerUps = [];
  let fuel = 100; // percent
  let score = 0;
  let gameOver = false;

  // ----- Helpers -----
  function rand(min, max) { return Math.random() * (max - min) + min; }
  function spawnAsteroid() {
    const size = rand(15, 40);
    asteroids.push({ x: rand(size, WIDTH - size), y: -size, r: size, speed: rand(1, 3) });
  }
  function spawnPowerUp() {
    const size = 15;
    powerUps.push({ x: rand(size, WIDTH - size), y: -size, size, speed: 1.5 });
  }
  function drawShip() {
    ctx.save();
    ctx.translate(ship.x, ship.y);
    ctx.fillStyle = '#0ff';
    ctx.beginPath();
    ctx.moveTo(0, -ship.size);
    ctx.lineTo(ship.size / 2, ship.size);
    ctx.lineTo(-ship.size / 2, ship.size);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  function drawAsteroids() {
    ctx.fillStyle = '#888';
    asteroids.forEach(a => {
      ctx.beginPath();
      ctx.arc(a.x, a.y, a.r, 0, Math.PI * 2);
      ctx.fill();
    });
  }
  function drawPowerUps() {
    ctx.fillStyle = '#ff0';
    powerUps.forEach(p => {
      ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
    });
  }
  function drawHUD() {
    ctx.fillStyle = '#fff';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Fuel: ${fuel.toFixed(0)}%`, 10, 20);
    ctx.fillText(`Score: ${score}`, 10, 40);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.6)';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);
      ctx.fillStyle = '#f66';
      ctx.textAlign = 'center';
      ctx.font = '48px sans-serif';
      ctx.fillText('Game Over', WIDTH / 2, HEIGHT / 2);
    }
  }
  function checkCollisions() {
    // ship vs asteroids
    for (const a of asteroids) {
      const dx = ship.x - a.x;
      const dy = ship.y - a.y;
      const dist = Math.hypot(dx, dy);
      if (dist < a.r + ship.size / 2) {
        gameOver = true;
        return;
      }
    }
    // ship vs power‑ups
    powerUps = powerUps.filter(p => {
      const dx = ship.x - p.x;
      const dy = ship.y - p.y;
      const dist = Math.hypot(dx, dy);
      if (dist < ship.size / 2 + p.size / 2) {
        fuel = Math.min(100, fuel + 20); // replenish fuel
        score += 10;
        return false; // remove power‑up
      }
      return true;
    });
  }
  function update() {
    if (gameOver) return;
    // move asteroids
    asteroids.forEach(a => a.y += a.speed);
    asteroids = asteroids.filter(a => a.y - a.r < HEIGHT);
    // move power‑ups
    powerUps.forEach(p => p.y += p.speed);
    powerUps = powerUps.filter(p => p.y - p.size < HEIGHT);
    // fuel consumption
    fuel -= 0.05;
    if (fuel <= 0) gameOver = true;
    checkCollisions();
    // spawn logic
    if (Math.random() < 0.02) spawnAsteroid();
    if (Math.random() < 0.005) spawnPowerUp();
  }
  function render() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);
    // starfield background (simple)
    ctx.fillStyle = '#111';
    ctx.fillRect(0, 0, WIDTH, HEIGHT);
    // draw stars (static for performance)
    ctx.fillStyle = '#555';
    for (let i = 0; i < 100; i++) {
      const sx = (i * 73) % WIDTH;
      const sy = ((i * 97) % HEIGHT);
      ctx.fillRect(sx, sy, 1, 1);
    }
    drawShip();
    drawAsteroids();
    drawPowerUps();
    drawHUD();
  }
  function loop() {
    update();
    render();
    requestAnimationFrame(loop);
  }
  // ----- Input -----
  window.addEventListener('keydown', e => {
    if (gameOver && e.key === 'Enter') { // restart
      asteroids = [];
      powerUps = [];
      fuel = 100;
      score = 0;
      gameOver = false;
    }
    switch (e.key) {
      case 'ArrowLeft':
        ship.x = Math.max(ship.size, ship.x - ship.speed);
        break;
      case 'ArrowRight':
        ship.x = Math.min(WIDTH - ship.size, ship.x + ship.speed);
        break;
      case 'ArrowUp':
        ship.y = Math.max(ship.size, ship.y - ship.speed);
        break;
      case 'ArrowDown':
        ship.y = Math.min(HEIGHT - ship.size, ship.y + ship.speed);
        break;
    }
  });

  loop();
})();
